function visual({ ui, state }) {
  const s = state({ detail: false });
  return () => ui.column([
    ui.toggle({ label: "Detail", value: s.detail, onChange: (v) => (s.detail = v) }),
    ui.mermaid(s.detail ? "flowchart LR
  A[Request] --> B{Cached?}
  B -->|yes| C[Reply]
  B -->|no| D[Render] --> C" : "flowchart LR
  A[Request] --> C[Reply]", { key: "flow" }),
    ui.mermaid("---
title: Turn
---
%% a comment
sequenceDiagram
  User->>Agent: ask
  Agent-->>User: answer"),
  ]);
}

